// The rules retain their original coordinates. Only the presentation is widened.
export function mapPoint(city){return{x:city.x*1.35-5,y:city.y*.69+5}}

function clipHalfPlane(polygon,a,b,c){const inside=p=>a*p.x+b*p.y<=c+1e-7,result=[];for(let i=0;i<polygon.length;i++){const p=polygon[i],q=polygon[(i+1)%polygon.length],pi=inside(p),qi=inside(q);if(pi)result.push(p);if(pi!==qi){const denominator=a*(q.x-p.x)+b*(q.y-p.y);if(Math.abs(denominator)>1e-8){const t=(c-a*p.x-b*p.y)/denominator;result.push({x:p.x+t*(q.x-p.x),y:p.y+t*(q.y-p.y)})}}}return result}
export function territoryCells(cities){const points=Object.values(cities).map(city=>({city,point:mapPoint(city)})),bounds=[{x:-4,y:0},{x:135,y:0},{x:135,y:84},{x:-4,y:84}];return points.map(({city,point})=>{let polygon=bounds;for(const other of points){if(other.city.id===city.id)continue;const a=2*(other.point.x-point.x),b=2*(other.point.y-point.y),c=other.point.x**2+other.point.y**2-point.x**2-point.y**2;polygon=clipHalfPlane(polygon,a,b,c);if(!polygon.length)break}return{id:city.id,owner:city.owner,polygon}})}
export function territoryMarkup(cities,factions){return territoryCells(cities).map(cell=>{const f=factions[cell.owner];if(!f||cell.polygon.length<3)return"";const points=cell.polygon.map(p=>`${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(" ");return`<polygon class="territory" points="${points}" fill="${f.color}" stroke="${f.color}"/>`}).join("")}

const ranges=[
  [18,27,8],[29,32,7],[24,47,7],[15,60,8],[12,76,6],[29,81,5],[44,47,6],[57,65,6],[89,20,7],[111,47,5],[116,65,5]
];
const forests=[[22,17],[53,20],[77,13],[83,44],[34,61],[56,76],[102,71],[117,34],[62,37],[14,49]];
export function terrainMarkup(){const mountains=ranges.map(([x,y,size],index)=>`<g class="mountain-cluster" transform="translate(${x} ${y})"><path d="M${-size} 4L-1 ${-size*.77}L${size*.25} 4Z"/><path d="M${-size*.22} 4L${size*.45} ${-size*.58}L${size} 4Z"/><path class="mountain-snow" d="M-3 ${-size*.56}L-1 ${-size*.77}L1 ${-size*.47}M${size*.25} ${-size*.37}L${size*.45} ${-size*.58}L${size*.67} ${-size*.33}"/><path class="mountain-hatch" d="M-4 1l2-2M1 1l2-2M5 2l2-2"/></g>`).join("");const trees=forests.map(([x,y],index)=>`<g class="forest-mark" transform="translate(${x} ${y})"><path d="M-2.1 1L-.9-2L.2 1ZM.2 2L1.5-2.8L2.8 2Z"/><path d="M-.9 1v2M1.5 2v2"/></g>`).join("");return`<path class="terrain-wash" d="M-5 50Q27 33 45 45T91 35T145 55V95H-5Z"/><path class="terrain-wash dry" d="M-5 7Q24 20 44 10T96 16T145 9V-5H-5Z"/><path class="river-bank" d="M42 -3Q37 13 51 20T76 31Q88 35 89 46T112 65"/><path class="river-main" d="M42 -3Q37 13 51 20T76 31Q88 35 89 46T112 65"/><path class="river-bank secondary" d="M22 39Q47 38 57 50T91 58"/><path class="river-main secondary" d="M22 39Q47 38 57 50T91 58"/>${mountains}${trees}<text class="region-name" x="21" y="13">西 凉</text><text class="region-name" x="70" y="9">河 北</text><text class="region-name" x="51" y="38">中 原</text><text class="region-name" x="20" y="70">益 州</text><text class="region-name" x="86" y="71">江 东</text>`}
